/// <summary>
/// A builder for creating transactions which uses a GraphQL client to
/// automatically resolve inputs. Use `finish` to finalize the transaction data.
/// </summary>
public interface IClientTransactionBuilder {
    /// <summary>
    /// Dry run the transaction.
    /// </summary>
    /// <exception cref="SdkFfiException"></exception>
    Task<DryRunResult> DryRun(bool @skipChecks = false);
    /// <summary>
    /// Execute the transaction and optionally wait for finalization.
    /// </summary>
    /// <exception cref="SdkFfiException"></exception>
    Task<TransactionEffects> Execute(TransactionSigner @signer, WaitForTx? @waitFor = null);
    /// <summary>
    /// Execute the transaction and optionally wait for finalization.
    /// </summary>
    /// <exception cref="SdkFfiException"></exception>
    Task<TransactionEffects> ExecuteWithSponsor(TransactionSigner @signer, TransactionSigner @sponsorSigner, WaitForTx? @waitFor = null);
    /// <summary>
    /// Set the expiration of the transaction to be a specific epoch.
    /// </summary>
    ClientTransactionBuilder Expiration(ulong @epoch);
    /// <summary>
    /// Convert this builder into a transaction.
    /// </summary>
    /// <exception cref="SdkFfiException"></exception>
    Task<Transaction> Finish();
    /// <summary>
    /// Add gas coins that will be consumed. Optional.
    /// </summary>
    ClientTransactionBuilder Gas(ObjectId[] @objectIds);
    /// <summary>
    /// Set the gas budget for the transaction.
    /// </summary>
    ClientTransactionBuilder GasBudget(ulong @budget);
    /// <summary>
    /// Set the gas price for the transaction.
    /// </summary>
    ClientTransactionBuilder GasPrice(ulong @price);
    /// <summary>
    /// Set the gas station sponsor.
    /// </summary>
    ClientTransactionBuilder GasStationSponsor(string @url, TimeSpan? @duration = null, Dictionary<string, string[]>? @headers = null);
    /// <summary>
    /// Make a move vector from a list of elements. The elements must all be of
    /// the type indicated by `type_tag`.
    /// </summary>
    ClientTransactionBuilder MakeMoveVec(MoveArg[] @elements, TypeTag @typeTag, string @name);
    /// <summary>
    /// Merge multiple coins into one.
    ///
    /// This method combines the balances of multiple coins of the same coin
    /// type into a single coin. The `primary_coin` will receive the balances
    /// from all `consumed_coins`. After merging, the `consumed_coins` will
    /// be consumed and no longer exist.
    /// </summary>
    ClientTransactionBuilder MergeCoins(PtbArgument @primaryCoin, PtbArgument[] @consumedCoins);
