class FfiConverterTypeClientTransactionBuilder: FfiConverter<ClientTransactionBuilder, IntPtr> {
    public static FfiConverterTypeClientTransactionBuilder INSTANCE = new FfiConverterTypeClientTransactionBuilder();


    public override IntPtr Lower(ClientTransactionBuilder value) {
        return value.CallWithPointer(thisPtr => thisPtr);
    }

    public override ClientTransactionBuilder Lift(IntPtr value) {
        return new ClientTransactionBuilder(value);
    }

    public override ClientTransactionBuilder Read(BigEndianStream stream) {
        return Lift(new IntPtr(stream.ReadLong()));
    }

    public override int AllocationSize(ClientTransactionBuilder value) {
        return 8;
    }

    public override void Write(ClientTransactionBuilder value, BigEndianStream stream) {
        stream.WriteLong(Lower(value).ToInt64());
    }
}



