    /// </summary>
    IntentScope Scope();
    /// <summary>
    /// Convert the signing intent to bytes.
    /// </summary>
    byte[] ToBytes();
    /// <summary>
    /// Get the version of the signing intent.
    /// </summary>
    IntentVersion Version();
}
