class FfiConverterTypeTransaction: FfiConverter<Transaction, IntPtr> {
    public static FfiConverterTypeTransaction INSTANCE = new FfiConverterTypeTransaction();


    public override IntPtr Lower(Transaction value) {
        return value.CallWithPointer(thisPtr => thisPtr);
    }

    public override Transaction Lift(IntPtr value) {
        return new Transaction(value);
    }

    public override Transaction Read(BigEndianStream stream) {
        return Lift(new IntPtr(stream.ReadLong()));
    }

    public override int AllocationSize(Transaction value) {
        return 8;
    }

    public override void Write(Transaction value, BigEndianStream stream) {
        stream.WriteLong(Lower(value).ToInt64());
    }
}



/// <summary>
/// A builder for creating transactions. Use `finish` to finalize the
/// transaction data.
/// </summary>
