    /// </summary>
    byte[] @contents, 
    /// <summary>
    /// UTC timestamp in milliseconds since epoch (1/1/1970)
    /// </summary>
    string @timestamp, 
    /// <summary>
    /// Structured contents of a Move value
    /// </summary>
    string @data, 
    /// <summary>
    /// Representation of a Move value in JSON
    /// </summary>
    string @json
) : IDisposable {
    public void Dispose() {
    FFIObjectUtil.DisposeAll(
            this.@packageId,
            this.@module,
            this.@sender,
            this.@type,
            this.@contents,
            this.@timestamp,
            this.@data,
