            @maxPageSize: FfiConverterInt32.INSTANCE.Read(stream),
            @maxQueryDepth: FfiConverterInt32.INSTANCE.Read(stream),
            @maxQueryNodes: FfiConverterInt32.INSTANCE.Read(stream),
            @maxQueryPayloadSize: FfiConverterInt32.INSTANCE.Read(stream),
            @maxTypeArgumentDepth: FfiConverterInt32.INSTANCE.Read(stream),
            @maxTypeArgumentWidth: FfiConverterInt32.INSTANCE.Read(stream),
            @maxTypeNodes: FfiConverterInt32.INSTANCE.Read(stream),
            @mutationTimeoutMs: FfiConverterInt32.INSTANCE.Read(stream),
            @requestTimeoutMs: FfiConverterInt32.INSTANCE.Read(stream)
        );
    }

    public override int AllocationSize(ServiceConfig value) {
        return 0
            + FfiConverterInt32.INSTANCE.AllocationSize(value.@defaultPageSize)
            + FfiConverterSequenceTypeFeature.INSTANCE.AllocationSize(value.@enabledFeatures)
            + FfiConverterInt32.INSTANCE.AllocationSize(value.@maxMoveValueDepth)
            + FfiConverterInt32.INSTANCE.AllocationSize(value.@maxOutputNodes)
            + FfiConverterInt32.INSTANCE.AllocationSize(value.@maxPageSize)
            + FfiConverterInt32.INSTANCE.AllocationSize(value.@maxQueryDepth)
            + FfiConverterInt32.INSTANCE.AllocationSize(value.@maxQueryNodes)
            + FfiConverterInt32.INSTANCE.AllocationSize(value.@maxQueryPayloadSize)
            + FfiConverterInt32.INSTANCE.AllocationSize(value.@maxTypeArgumentDepth)
            + FfiConverterInt32.INSTANCE.AllocationSize(value.@maxTypeArgumentWidth)
            + FfiConverterInt32.INSTANCE.AllocationSize(value.@maxTypeNodes)
            + FfiConverterInt32.INSTANCE.AllocationSize(value.@mutationTimeoutMs)
            + FfiConverterInt32.INSTANCE.AllocationSize(value.@requestTimeoutMs);
    }

    public override void Write(ServiceConfig value, BigEndianStream stream) {
            FfiConverterInt32.INSTANCE.Write(value.@defaultPageSize, stream);
            FfiConverterSequenceTypeFeature.INSTANCE.Write(value.@enabledFeatures, stream);
            FfiConverterInt32.INSTANCE.Write(value.@maxMoveValueDepth, stream);
            FfiConverterInt32.INSTANCE.Write(value.@maxOutputNodes, stream);
            FfiConverterInt32.INSTANCE.Write(value.@maxPageSize, stream);
            FfiConverterInt32.INSTANCE.Write(value.@maxQueryDepth, stream);
            FfiConverterInt32.INSTANCE.Write(value.@maxQueryNodes, stream);
            FfiConverterInt32.INSTANCE.Write(value.@maxQueryPayloadSize, stream);
            FfiConverterInt32.INSTANCE.Write(value.@maxTypeArgumentDepth, stream);
            FfiConverterInt32.INSTANCE.Write(value.@maxTypeArgumentWidth, stream);
            FfiConverterInt32.INSTANCE.Write(value.@maxTypeNodes, stream);
            FfiConverterInt32.INSTANCE.Write(value.@mutationTimeoutMs, stream);
            FfiConverterInt32.INSTANCE.Write(value.@requestTimeoutMs, stream);
    }
}



