/// <param name="inactive_pools_id">
/// Object ID of the `Table` storing the inactive staking pools.
/// </param>
/// <param name="inactive_pools_size">
/// Size of the inactive pools `Table`.
/// </param>
/// <param name="pending_active_validators_id">
/// Object ID of the wrapped object `TableVec` storing the pending active
/// validators.
/// </param>
/// <param name="pending_active_validators_size">
/// Size of the pending active validators table.
/// </param>
/// <param name="pending_removals">
/// Validators that are pending removal from the active validator set,
/// expressed as indices in to `activeValidators`.
/// </param>
/// <param name="staking_pool_mappings_id">
/// Object ID of the `Table` storing the mapping from staking pool ids to
/// the addresses of the corresponding validators. This is needed
/// because a validator's address can potentially change but the object
/// ID of its pool will not.
/// </param>
/// <param name="staking_pool_mappings_size">
/// Size of the stake pool mappings `Table`.
/// </param>
/// <param name="total_stake">
/// Total amount of stake for all active validators at the beginning of the
/// epoch.
/// </param>
/// <param name="validator_candidates_size">
/// Size of the validator candidates `Table`.
/// </param>
/// <param name="validator_candidates_id">
/// Object ID of the `Table` storing the validator candidates.
/// </param>
public record ValidatorSet (
    /// <summary>
    /// Object ID of the `Table` storing the inactive staking pools.
    /// </summary>
    ObjectId? @inactivePoolsId = null, 
    /// <summary>
    /// Size of the inactive pools `Table`.
    /// </summary>
    int? @inactivePoolsSize = null, 
    /// <summary>
    /// Object ID of the wrapped object `TableVec` storing the pending active
    /// validators.
    /// </summary>
    ObjectId? @pendingActiveValidatorsId = null, 
    /// <summary>
    /// Size of the pending active validators table.
    /// </summary>
    int? @pendingActiveValidatorsSize = null, 
    /// <summary>
    /// Validators that are pending removal from the active validator set,
    /// expressed as indices in to `activeValidators`.
    /// </summary>
    int[]? @pendingRemovals = null, 
    /// <summary>
    /// Object ID of the `Table` storing the mapping from staking pool ids to
    /// the addresses of the corresponding validators. This is needed
    /// because a validator's address can potentially change but the object
    /// ID of its pool will not.
    /// </summary>
    ObjectId? @stakingPoolMappingsId = null, 
    /// <summary>
    /// Size of the stake pool mappings `Table`.
    /// </summary>
    int? @stakingPoolMappingsSize = null, 
    /// <summary>
    /// Total amount of stake for all active validators at the beginning of the
    /// epoch.
    /// </summary>
    string? @totalStake = null, 
    /// <summary>
    /// Size of the validator candidates `Table`.
    /// </summary>
    int? @validatorCandidatesSize = null, 
    /// <summary>
    /// Object ID of the `Table` storing the validator candidates.
    /// </summary>
    ObjectId? @validatorCandidatesId = null
) : IDisposable {
    public void Dispose() {
    FFIObjectUtil.DisposeAll(
            this.@inactivePoolsId,
            this.@inactivePoolsSize,
            this.@pendingActiveValidatorsId,
            this.@pendingActiveValidatorsSize,
            this.@pendingRemovals,
            this.@stakingPoolMappingsId,
            this.@stakingPoolMappingsSize,
            this.@totalStake,
            this.@validatorCandidatesSize,
            this.@validatorCandidatesId);
    }
}

