public enum BatchSendStatusType: int {
    
    InProgress,
    Succeeded,
    Discarded
}

class FfiConverterTypeBatchSendStatusType: FfiConverterRustBuffer<BatchSendStatusType> {
    public static FfiConverterTypeBatchSendStatusType INSTANCE = new FfiConverterTypeBatchSendStatusType();

    public override BatchSendStatusType Read(BigEndianStream stream) {
        var value = stream.ReadInt() - 1;
        if (Enum.IsDefined(typeof(BatchSendStatusType), value)) {
            return (BatchSendStatusType)value;
        } else {
            throw new InternalException(string.Format("invalid enum value '{0}' in FfiConverterTypeBatchSendStatusType.Read()", value));
        }
    }

    public override int AllocationSize(BatchSendStatusType value) {
        return 4;
    }

    public override void Write(BatchSendStatusType value, BigEndianStream stream) {
        stream.WriteInt((int)value + 1);
    }
}







/// <summary>
/// An error with an argument to a command
///
/// # BCS
///
/// The BCS serialized form for this type is defined by the following ABNF:
///
/// ```text
/// command-argument-error =  type-mismatch
/// =/ invalid-bcs-bytes
/// =/ invalid-usage-of-pure-argument
/// =/ invalid-argument-to-private-entry-function
/// =/ index-out-of-bounds
/// =/ secondary-index-out-of-bound
/// =/ invalid-result-arity
/// =/ invalid-gas-coin-usage
/// =/ invalid-value-usage
/// =/ invalid-object-by-value
/// =/ invalid-object-by-mut-ref
/// =/ shared-object-operation-not-allowed
///
/// type-mismatch                               = %d00
/// invalid-bcs-bytes                           = %d01
/// invalid-usage-of-pure-argument              = %d02
/// invalid-argument-to-private-entry-function  = %d03
/// index-out-of-bounds                         = %d04 u16
/// secondary-index-out-of-bound                = %d05 u16 u16
/// invalid-result-arity                        = %d06 u16
/// invalid-gas-coin-usage                      = %d07
/// invalid-value-usage                         = %d08
/// invalid-object-by-value                     = %d09
/// invalid-object-by-mut-ref                   = %d10
/// shared-object-operation-not-allowed         = %d11
/// ```
/// </summary>
public record CommandArgumentError {
    
    /// <summary>
    /// The type of the value does not match the expected type
    /// </summary>
    public record TypeMismatch: CommandArgumentError {}
    
    
    /// <summary>
    /// The argument cannot be deserialized into a value of the specified type
    /// </summary>
    public record InvalidBcsBytes: CommandArgumentError {}
    
    
    /// <summary>
    /// The argument cannot be instantiated from raw bytes
    /// </summary>
    public record InvalidUsageOfPureArgument: CommandArgumentError {}
    
    
    /// <summary>
    /// Invalid argument to private entry function.
    /// Private entry functions cannot take arguments from other Move functions.
    /// </summary>
    public record InvalidArgumentToPrivateEntryFunction: CommandArgumentError {}
    
    
    /// <summary>
    /// Out of bounds access to input or results
    /// </summary>
    public record IndexOutOfBounds (
        ushort @index
    ) : CommandArgumentError {}
    
    /// <summary>
    /// Out of bounds access to subresult
    /// </summary>
    public record SecondaryIndexOutOfBounds (
        ushort @result,
        ushort @subresult
    ) : CommandArgumentError {}
    
    /// <summary>
    /// Invalid usage of result.
    /// Expected a single result but found either no return value or multiple.
    /// </summary>
    public record InvalidResultArity (
        ushort @result
    ) : CommandArgumentError {}
    
    /// <summary>
    /// Invalid usage of Gas coin.
    /// The Gas coin can only be used by-value with a TransferObjects command.
    /// </summary>
    public record InvalidGasCoinUsage: CommandArgumentError {}
    
    
    /// <summary>
    /// Invalid usage of move value.
    /// </summary>
    public record InvalidValueUsage: CommandArgumentError {}
    
    
    /// <summary>
    /// Immutable objects cannot be passed by-value.
    /// </summary>
    public record InvalidObjectByValue: CommandArgumentError {}
    
    
    /// <summary>
    /// Immutable objects cannot be passed by mutable reference, &mut.
    /// </summary>
    public record InvalidObjectByMutRef: CommandArgumentError {}
    
    
    /// <summary>
    /// Shared object operations such a wrapping, freezing, or converting to
    /// owned are not allowed.
    /// </summary>
    public record SharedObjectOperationNotAllowed: CommandArgumentError {}
    
    
    /// <summary>
    /// Invalid argument arity. Expected a single argument but found a result
    /// that expanded to multiple arguments.
    /// </summary>
    public record InvalidArgumentArity: CommandArgumentError {}
    
    

    
}

class FfiConverterTypeCommandArgumentError : FfiConverterRustBuffer<CommandArgumentError>{
    public static FfiConverterRustBuffer<CommandArgumentError> INSTANCE = new FfiConverterTypeCommandArgumentError();

    public override CommandArgumentError Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new CommandArgumentError.TypeMismatch(
                );
            case 2:
                return new CommandArgumentError.InvalidBcsBytes(
                );
            case 3:
                return new CommandArgumentError.InvalidUsageOfPureArgument(
                );
            case 4:
                return new CommandArgumentError.InvalidArgumentToPrivateEntryFunction(
                );
            case 5:
                return new CommandArgumentError.IndexOutOfBounds(
                    FfiConverterUInt16.INSTANCE.Read(stream)
                );
            case 6:
                return new CommandArgumentError.SecondaryIndexOutOfBounds(
                    FfiConverterUInt16.INSTANCE.Read(stream),
                    FfiConverterUInt16.INSTANCE.Read(stream)
                );
            case 7:
                return new CommandArgumentError.InvalidResultArity(
                    FfiConverterUInt16.INSTANCE.Read(stream)
                );
            case 8:
                return new CommandArgumentError.InvalidGasCoinUsage(
                );
            case 9:
                return new CommandArgumentError.InvalidValueUsage(
                );
            case 10:
                return new CommandArgumentError.InvalidObjectByValue(
                );
            case 11:
                return new CommandArgumentError.InvalidObjectByMutRef(
                );
            case 12:
                return new CommandArgumentError.SharedObjectOperationNotAllowed(
                );
            case 13:
                return new CommandArgumentError.InvalidArgumentArity(
                );
            default:
                throw new InternalException(string.Format("invalid enum value '{0}' in FfiConverterTypeCommandArgumentError.Read()", value));
        }
    }

    public override int AllocationSize(CommandArgumentError value) {
        switch (value) {
            case CommandArgumentError.TypeMismatch variant_value:
                return 4;
            case CommandArgumentError.InvalidBcsBytes variant_value:
                return 4;
            case CommandArgumentError.InvalidUsageOfPureArgument variant_value:
                return 4;
            case CommandArgumentError.InvalidArgumentToPrivateEntryFunction variant_value:
                return 4;
            case CommandArgumentError.IndexOutOfBounds variant_value:
                return 4
                    + FfiConverterUInt16.INSTANCE.AllocationSize(variant_value.@index);
            case CommandArgumentError.SecondaryIndexOutOfBounds variant_value:
                return 4
                    + FfiConverterUInt16.INSTANCE.AllocationSize(variant_value.@result)
                    + FfiConverterUInt16.INSTANCE.AllocationSize(variant_value.@subresult);
            case CommandArgumentError.InvalidResultArity variant_value:
                return 4
                    + FfiConverterUInt16.INSTANCE.AllocationSize(variant_value.@result);
            case CommandArgumentError.InvalidGasCoinUsage variant_value:
                return 4;
            case CommandArgumentError.InvalidValueUsage variant_value:
                return 4;
            case CommandArgumentError.InvalidObjectByValue variant_value:
                return 4;
            case CommandArgumentError.InvalidObjectByMutRef variant_value:
                return 4;
            case CommandArgumentError.SharedObjectOperationNotAllowed variant_value:
                return 4;
            case CommandArgumentError.InvalidArgumentArity variant_value:
                return 4;
            default:
                throw new InternalException(string.Format("invalid enum value '{0}' in FfiConverterTypeCommandArgumentError.AllocationSize()", value));
        }
    }

    public override void Write(CommandArgumentError value, BigEndianStream stream) {
        switch (value) {
            case CommandArgumentError.TypeMismatch variant_value:
                stream.WriteInt(1);
                break;
            case CommandArgumentError.InvalidBcsBytes variant_value:
                stream.WriteInt(2);
                break;
            case CommandArgumentError.InvalidUsageOfPureArgument variant_value:
                stream.WriteInt(3);
                break;
            case CommandArgumentError.InvalidArgumentToPrivateEntryFunction variant_value:
                stream.WriteInt(4);
                break;
            case CommandArgumentError.IndexOutOfBounds variant_value:
                stream.WriteInt(5);
                FfiConverterUInt16.INSTANCE.Write(variant_value.@index, stream);
                break;
            case CommandArgumentError.SecondaryIndexOutOfBounds variant_value:
                stream.WriteInt(6);
                FfiConverterUInt16.INSTANCE.Write(variant_value.@result, stream);
                FfiConverterUInt16.INSTANCE.Write(variant_value.@subresult, stream);
                break;
            case CommandArgumentError.InvalidResultArity variant_value:
                stream.WriteInt(7);
                FfiConverterUInt16.INSTANCE.Write(variant_value.@result, stream);
                break;
            case CommandArgumentError.InvalidGasCoinUsage variant_value:
                stream.WriteInt(8);
                break;
            case CommandArgumentError.InvalidValueUsage variant_value:
                stream.WriteInt(9);
                break;
            case CommandArgumentError.InvalidObjectByValue variant_value:
                stream.WriteInt(10);
                break;
            case CommandArgumentError.InvalidObjectByMutRef variant_value:
                stream.WriteInt(11);
                break;
            case CommandArgumentError.SharedObjectOperationNotAllowed variant_value:
                stream.WriteInt(12);
                break;
            case CommandArgumentError.InvalidArgumentArity variant_value:
                stream.WriteInt(13);
                break;
            default:
                throw new InternalException(string.Format("invalid enum value '{0}' in FfiConverterTypeCommandArgumentError.Write()", value));
        }
    }
}







/// <summary>
/// Pagination direction.
/// </summary>
public enum Direction: int {
    
    Forward,
    Backward
}

class FfiConverterTypeDirection: FfiConverterRustBuffer<Direction> {
    public static FfiConverterTypeDirection INSTANCE = new FfiConverterTypeDirection();

    public override Direction Read(BigEndianStream stream) {
        var value = stream.ReadInt() - 1;
        if (Enum.IsDefined(typeof(Direction), value)) {
            return (Direction)value;
        } else {
            throw new InternalException(string.Format("invalid enum value '{0}' in FfiConverterTypeDirection.Read()", value));
        }
    }

    public override int AllocationSize(Direction value) {
        return 4;
    }

    public override void Write(Direction value, BigEndianStream stream) {
        stream.WriteInt((int)value + 1);
    }
}







/// <summary>
/// An error that can occur during the execution of a transaction
///
/// # BCS
///
/// The BCS serialized form for this type is defined by the following ABNF:
///
/// ```text
///
/// execution-error =  insufficient-gas
/// =/ invalid-gas-object
/// =/ invariant-violation
/// =/ feature-not-yet-supported
/// =/ object-too-big
/// =/ package-too-big
/// =/ circular-object-ownership
/// =/ insufficient-coin-balance
/// =/ coin-balance-overflow
/// =/ publish-error-non-zero-address
/// =/ iota-move-verification-error
/// =/ move-primitive-runtime-error
/// =/ move-abort
/// =/ vm-verification-or-deserialization-error
/// =/ vm-invariant-violation
/// =/ function-not-found
/// =/ arity-mismatch
/// =/ type-arity-mismatch
/// =/ non-entry-function-invoked
/// =/ command-argument-error
/// =/ type-argument-error
/// =/ unused-value-without-drop
/// =/ invalid-public-function-return-type
/// =/ invalid-transfer-object
/// =/ effects-too-large
/// =/ publish-upgrade-missing-dependency
/// =/ publish-upgrade-dependency-downgrade
/// =/ package-upgrade-error
/// =/ written-objects-too-large
/// =/ certificate-denied
/// =/ iota-move-verification-timeout
/// =/ shared-object-operation-not-allowed
/// =/ input-object-deleted
/// =/ execution-cancelled-due-to-shared-object-congestion
/// =/ address-denied-for-coin
/// =/ coin-type-global-pause
/// =/ execution-cancelled-due-to-randomness-unavailable
///
/// insufficient-gas                                    = %d00
/// invalid-gas-object                                  = %d01
/// invariant-violation                                 = %d02
/// feature-not-yet-supported                           = %d03
/// object-too-big                                      = %d04 u64 u64
/// package-too-big                                     = %d05 u64 u64
/// circular-object-ownership                           = %d06 object-id
/// insufficient-coin-balance                           = %d07
/// coin-balance-overflow                               = %d08
/// publish-error-non-zero-address                      = %d09
/// iota-move-verification-error                        = %d10
/// move-primitive-runtime-error                        = %d11 (option move-location)
/// move-abort                                          = %d12 move-location u64
/// vm-verification-or-deserialization-error            = %d13
/// vm-invariant-violation                              = %d14
/// function-not-found                                  = %d15
/// arity-mismatch                                      = %d16
/// type-arity-mismatch                                 = %d17
/// non-entry-function-invoked                          = %d18
/// command-argument-error                              = %d19 u16 command-argument-error
/// type-argument-error                                 = %d20 u16 type-argument-error
/// unused-value-without-drop                           = %d21 u16 u16
/// invalid-public-function-return-type                 = %d22 u16
/// invalid-transfer-object                             = %d23
/// effects-too-large                                   = %d24 u64 u64
/// publish-upgrade-missing-dependency                  = %d25
/// publish-upgrade-dependency-downgrade                = %d26
/// package-upgrade-error                               = %d27 package-upgrade-error
/// written-objects-too-large                           = %d28 u64 u64
/// certificate-denied                                  = %d29
/// iota-move-verification-timeout                      = %d30
/// shared-object-operation-not-allowed                 = %d31
/// input-object-deleted                                = %d32
/// execution-cancelled-due-to-shared-object-congestion = %d33 (vector object-id)
/// address-denied-for-coin                             = %d34 address string
/// coin-type-global-pause                              = %d35 string
/// execution-cancelled-due-to-randomness-unavailable   = %d36
/// ```
/// </summary>
public record ExecutionError: IDisposable  {
    
    /// <summary>
    /// Insufficient Gas
    /// </summary>
    public record InsufficientGas: ExecutionError {}
    
    
    /// <summary>
    /// Invalid Gas Object.
    /// </summary>
    public record InvalidGasObject: ExecutionError {}
    
    
    /// <summary>
    /// Invariant Violation
    /// </summary>
    public record InvariantViolation: ExecutionError {}
    
    
    /// <summary>
    /// Attempted to used feature that is not supported yet
    /// </summary>
    public record FeatureNotYetSupported: ExecutionError {}
    
    
    /// <summary>
    /// Move object is larger than the maximum allowed size
    /// </summary>
    public record ObjectTooBig (
        ulong @objectSize,
        ulong @maxObjectSize
    ) : ExecutionError {}
    
    /// <summary>
    /// Package is larger than the maximum allowed size
    /// </summary>
    public record PackageTooBig (
        ulong @objectSize,
        ulong @maxObjectSize
    ) : ExecutionError {}
    
    /// <summary>
    /// Circular Object Ownership
    /// </summary>
    public record CircularObjectOwnership (
        ObjectId @object
    ) : ExecutionError {}
    
    /// <summary>
    /// Insufficient coin balance for requested operation
    /// </summary>
    public record InsufficientCoinBalance: ExecutionError {}
    
    
    /// <summary>
    /// Coin balance overflowed an u64
    /// </summary>
    public record CoinBalanceOverflow: ExecutionError {}
    
    
    /// <summary>
    /// Publish Error, Non-zero Address.
    /// The modules in the package must have their self-addresses set to zero.
    /// </summary>
    public record PublishErrorNonZeroAddress: ExecutionError {}
    
    
    /// <summary>
    /// IOTA Move Bytecode Verification Error.
    /// </summary>
    public record IotaMoveVerification: ExecutionError {}
    
    
    /// <summary>
    /// Error from a non-abort instruction.
    /// Possible causes:
    /// Arithmetic error, stack overflow, max value depth, etc."
    /// </summary>
    public record MovePrimitiveRuntime (
        MoveLocation? @location
    ) : ExecutionError {}
    
    /// <summary>
    /// Move runtime abort
    /// </summary>
    public record MoveAbort (
        MoveLocation @location,
        ulong @code
    ) : ExecutionError {}
    
    /// <summary>
    /// Bytecode verification error.
    /// </summary>
    public record VmVerificationOrDeserialization: ExecutionError {}
    
    
    /// <summary>
    /// MoveVm invariant violation
    /// </summary>
    public record VmInvariantViolation: ExecutionError {}
    
    
    /// <summary>
    /// Function not found
    /// </summary>
    public record FunctionNotFound: ExecutionError {}
    
    
    /// <summary>
    /// Arity mismatch for Move function.
    /// The number of arguments does not match the number of parameters
    /// </summary>
    public record ArityMismatch: ExecutionError {}
    
    
    /// <summary>
    /// Type arity mismatch for Move function.
    /// Mismatch between the number of actual versus expected type arguments.
    /// </summary>
    public record TypeArityMismatch: ExecutionError {}
    
    
    /// <summary>
    /// Non Entry Function Invoked. Move Call must start with an entry function.
    /// </summary>
    public record NonEntryFunctionInvoked: ExecutionError {}
    
    
    /// <summary>
    /// Invalid command argument
    /// </summary>
    public record CommandArgument (
        ushort @argument,
        CommandArgumentError @kind
    ) : ExecutionError {}
    
    /// <summary>
    /// Type argument error
    /// </summary>
    public record TypeArgument (
        ushort @typeArgument,
        TypeArgumentError @kind
    ) : ExecutionError {}
    
    /// <summary>
    /// Unused result without the drop ability.
    /// </summary>
    public record UnusedValueWithoutDrop (
        ushort @result,
        ushort @subresult
    ) : ExecutionError {}
    
    /// <summary>
    /// Invalid public Move function signature.
    /// Unsupported return type for return value
    /// </summary>
    public record InvalidPublicFunctionReturnType (
        ushort @index
    ) : ExecutionError {}
    
    /// <summary>
    /// Invalid Transfer Object, object does not have public transfer.
    /// </summary>
    public record InvalidTransferObject: ExecutionError {}
    
    
    /// <summary>
    /// Effects from the transaction are too large
    /// </summary>
    public record EffectsTooLarge (
        ulong @currentSize,
        ulong @maxSize
    ) : ExecutionError {}
    
    /// <summary>
    /// Publish or Upgrade is missing dependency
    /// </summary>
    public record PublishUpgradeMissingDependency: ExecutionError {}
    
    
    /// <summary>
    /// Publish or Upgrade dependency downgrade.
    ///
    /// Indirect (transitive) dependency of published or upgraded package has
    /// been assigned an on-chain version that is less than the version
    /// required by one of the package's transitive dependencies.
    /// </summary>
    public record PublishUpgradeDependencyDowngrade: ExecutionError {}
    
    
    /// <summary>
    /// Invalid package upgrade
    /// </summary>
    public record PackageUpgrade (
        PackageUpgradeError @kind
    ) : ExecutionError {}
    
    /// <summary>
    /// Indicates the transaction tried to write objects too large to storage
    /// </summary>
    public record WrittenObjectsTooLarge (
        ulong @objectSize,
        ulong @maxObjectSize
    ) : ExecutionError {}
    
    /// <summary>
    /// Certificate is on the deny list
    /// </summary>
    public record CertificateDenied: ExecutionError {}
    
    
    /// <summary>
    /// IOTA Move Bytecode verification timed out.
    /// </summary>
    public record IotaMoveVerificationTimeout: ExecutionError {}
    
    
    /// <summary>
    /// The requested shared object operation is not allowed
    /// </summary>
    public record SharedObjectOperationNotAllowed: ExecutionError {}
    
    
    /// <summary>
    /// Requested shared object has been deleted
    /// </summary>
    public record InputObjectDeleted: ExecutionError {}
    
    
    /// <summary>
    /// Certificate is cancelled due to congestion on shared objects
    /// </summary>
    public record ExecutionCancelledDueToSharedObjectCongestion (
        ObjectId[] @congestedObjects
    ) : ExecutionError {}
    
    /// <summary>
    /// Certificate is cancelled due to congestion on shared objects;
    /// suggested gas price can be used to give this certificate more priority.
    /// </summary>
    public record ExecutionCancelledDueToSharedObjectCongestionV2 (
        ObjectId[] @congestedObjects,
        ulong @suggestedGasPrice
    ) : ExecutionError {}
    
    /// <summary>
    /// Address is denied for this coin type
    /// </summary>
    public record AddressDeniedForCoin (
        Address @address,
        string @coinType
    ) : ExecutionError {}
    
    /// <summary>
    /// Coin type is globally paused for use
    /// </summary>
    public record CoinTypeGlobalPause (
        string @coinType
    ) : ExecutionError {}
    
    /// <summary>
    /// Certificate is cancelled because randomness could not be generated this
    /// epoch
    /// </summary>
    public record ExecutionCancelledDueToRandomnessUnavailable: ExecutionError {}
    
    
    /// <summary>
    /// A valid linkage was unable to be determined for the transaction or one
    /// of its commands.
    /// </summary>
    public record InvalidLinkage: ExecutionError {}
    
    

    
    public void Dispose() {
        switch (this) {
            case ExecutionError.InsufficientGas variant_value:
                break;
            case ExecutionError.InvalidGasObject variant_value:
                break;
            case ExecutionError.InvariantViolation variant_value:
                break;
            case ExecutionError.FeatureNotYetSupported variant_value:
                break;
            case ExecutionError.ObjectTooBig variant_value:
                
    FFIObjectUtil.DisposeAll(
            variant_value.@objectSize,
            variant_value.@maxObjectSize);
                break;
            case ExecutionError.PackageTooBig variant_value:
                
    FFIObjectUtil.DisposeAll(
            variant_value.@objectSize,
            variant_value.@maxObjectSize);
                break;
            case ExecutionError.CircularObjectOwnership variant_value:
                
    FFIObjectUtil.DisposeAll(
            variant_value.@object);
                break;
            case ExecutionError.InsufficientCoinBalance variant_value:
                break;
            case ExecutionError.CoinBalanceOverflow variant_value:
                break;
            case ExecutionError.PublishErrorNonZeroAddress variant_value:
                break;
            case ExecutionError.IotaMoveVerification variant_value:
                break;
            case ExecutionError.MovePrimitiveRuntime variant_value:
                
    FFIObjectUtil.DisposeAll(
            variant_value.@location);
                break;
            case ExecutionError.MoveAbort variant_value:
                
    FFIObjectUtil.DisposeAll(
            variant_value.@location,
            variant_value.@code);
                break;
            case ExecutionError.VmVerificationOrDeserialization variant_value:
                break;
            case ExecutionError.VmInvariantViolation variant_value:
                break;
            case ExecutionError.FunctionNotFound variant_value:
                break;
            case ExecutionError.ArityMismatch variant_value:
                break;
            case ExecutionError.TypeArityMismatch variant_value:
                break;
            case ExecutionError.NonEntryFunctionInvoked variant_value:
                break;
            case ExecutionError.CommandArgument variant_value:
                
    FFIObjectUtil.DisposeAll(
            variant_value.@argument,
            variant_value.@kind);
                break;
            case ExecutionError.TypeArgument variant_value:
                
    FFIObjectUtil.DisposeAll(
            variant_value.@typeArgument,
            variant_value.@kind);
                break;
            case ExecutionError.UnusedValueWithoutDrop variant_value:
                
    FFIObjectUtil.DisposeAll(
            variant_value.@result,
            variant_value.@subresult);
                break;
            case ExecutionError.InvalidPublicFunctionReturnType variant_value:
                
    FFIObjectUtil.DisposeAll(
            variant_value.@index);
                break;
            case ExecutionError.InvalidTransferObject variant_value:
                break;
            case ExecutionError.EffectsTooLarge variant_value:
                
    FFIObjectUtil.DisposeAll(
            variant_value.@currentSize,
            variant_value.@maxSize);
                break;
            case ExecutionError.PublishUpgradeMissingDependency variant_value:
                break;
            case ExecutionError.PublishUpgradeDependencyDowngrade variant_value:
                break;
            case ExecutionError.PackageUpgrade variant_value:
                
    FFIObjectUtil.DisposeAll(
            variant_value.@kind);
                break;
            case ExecutionError.WrittenObjectsTooLarge variant_value:
                
    FFIObjectUtil.DisposeAll(
            variant_value.@objectSize,
            variant_value.@maxObjectSize);
                break;
            case ExecutionError.CertificateDenied variant_value:
                break;
            case ExecutionError.IotaMoveVerificationTimeout variant_value:
                break;
            case ExecutionError.SharedObjectOperationNotAllowed variant_value:
                break;
            case ExecutionError.InputObjectDeleted variant_value:
                break;
            case ExecutionError.ExecutionCancelledDueToSharedObjectCongestion variant_value:
                
    FFIObjectUtil.DisposeAll(
            variant_value.@congestedObjects);
                break;
            case ExecutionError.ExecutionCancelledDueToSharedObjectCongestionV2 variant_value:
                
    FFIObjectUtil.DisposeAll(
            variant_value.@congestedObjects,
            variant_value.@suggestedGasPrice);
                break;
            case ExecutionError.AddressDeniedForCoin variant_value:
                
    FFIObjectUtil.DisposeAll(
            variant_value.@address,
            variant_value.@coinType);
                break;
            case ExecutionError.CoinTypeGlobalPause variant_value:
                
    FFIObjectUtil.DisposeAll(
            variant_value.@coinType);
                break;
            case ExecutionError.ExecutionCancelledDueToRandomnessUnavailable variant_value:
                break;
            case ExecutionError.InvalidLinkage variant_value:
                break;
            default:
                throw new InternalException(string.Format("invalid enum value '{0}' in ExecutionError.Dispose()", this));
        }
    }
    
}

class FfiConverterTypeExecutionError : FfiConverterRustBuffer<ExecutionError>{
    public static FfiConverterRustBuffer<ExecutionError> INSTANCE = new FfiConverterTypeExecutionError();

    public override ExecutionError Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new ExecutionError.InsufficientGas(
                );
            case 2:
                return new ExecutionError.InvalidGasObject(
                );
            case 3:
                return new ExecutionError.InvariantViolation(
                );
            case 4:
                return new ExecutionError.FeatureNotYetSupported(
                );
            case 5:
                return new ExecutionError.ObjectTooBig(
                    FfiConverterUInt64.INSTANCE.Read(stream),
                    FfiConverterUInt64.INSTANCE.Read(stream)
                );
            case 6:
                return new ExecutionError.PackageTooBig(
                    FfiConverterUInt64.INSTANCE.Read(stream),
                    FfiConverterUInt64.INSTANCE.Read(stream)
                );
            case 7:
                return new ExecutionError.CircularObjectOwnership(
                    FfiConverterTypeObjectId.INSTANCE.Read(stream)
                );
            case 8:
                return new ExecutionError.InsufficientCoinBalance(
                );
            case 9:
                return new ExecutionError.CoinBalanceOverflow(
                );
            case 10:
                return new ExecutionError.PublishErrorNonZeroAddress(
                );
            case 11:
                return new ExecutionError.IotaMoveVerification(
                );
            case 12:
                return new ExecutionError.MovePrimitiveRuntime(
                    FfiConverterOptionalTypeMoveLocation.INSTANCE.Read(stream)
                );
            case 13:
                return new ExecutionError.MoveAbort(
                    FfiConverterTypeMoveLocation.INSTANCE.Read(stream),
                    FfiConverterUInt64.INSTANCE.Read(stream)
                );
            case 14:
                return new ExecutionError.VmVerificationOrDeserialization(
                );
            case 15:
                return new ExecutionError.VmInvariantViolation(
                );
            case 16:
                return new ExecutionError.FunctionNotFound(
                );
            case 17:
                return new ExecutionError.ArityMismatch(
                );
            case 18:
                return new ExecutionError.TypeArityMismatch(
                );
            case 19:
                return new ExecutionError.NonEntryFunctionInvoked(
                );
            case 20:
                return new ExecutionError.CommandArgument(
                    FfiConverterUInt16.INSTANCE.Read(stream),
                    FfiConverterTypeCommandArgumentError.INSTANCE.Read(stream)
                );
            case 21:
                return new ExecutionError.TypeArgument(
                    FfiConverterUInt16.INSTANCE.Read(stream),
                    FfiConverterTypeTypeArgumentError.INSTANCE.Read(stream)
                );
            case 22:
                return new ExecutionError.UnusedValueWithoutDrop(
                    FfiConverterUInt16.INSTANCE.Read(stream),
                    FfiConverterUInt16.INSTANCE.Read(stream)
                );
            case 23:
                return new ExecutionError.InvalidPublicFunctionReturnType(
                    FfiConverterUInt16.INSTANCE.Read(stream)
                );
            case 24:
                return new ExecutionError.InvalidTransferObject(
                );
            case 25:
                return new ExecutionError.EffectsTooLarge(
                    FfiConverterUInt64.INSTANCE.Read(stream),
                    FfiConverterUInt64.INSTANCE.Read(stream)
                );
            case 26:
                return new ExecutionError.PublishUpgradeMissingDependency(
                );
            case 27:
                return new ExecutionError.PublishUpgradeDependencyDowngrade(
                );
            case 28:
                return new ExecutionError.PackageUpgrade(
                    FfiConverterTypePackageUpgradeError.INSTANCE.Read(stream)
                );
            case 29:
                return new ExecutionError.WrittenObjectsTooLarge(
                    FfiConverterUInt64.INSTANCE.Read(stream),
                    FfiConverterUInt64.INSTANCE.Read(stream)
                );
            case 30:
                return new ExecutionError.CertificateDenied(
                );
            case 31:
                return new ExecutionError.IotaMoveVerificationTimeout(
                );
            case 32:
                return new ExecutionError.SharedObjectOperationNotAllowed(
                );
            case 33:
                return new ExecutionError.InputObjectDeleted(
                );
            case 34:
                return new ExecutionError.ExecutionCancelledDueToSharedObjectCongestion(
                    FfiConverterSequenceTypeObjectId.INSTANCE.Read(stream)
                );
            case 35:
                return new ExecutionError.ExecutionCancelledDueToSharedObjectCongestionV2(
                    FfiConverterSequenceTypeObjectId.INSTANCE.Read(stream),
                    FfiConverterUInt64.INSTANCE.Read(stream)
                );
            case 36:
                return new ExecutionError.AddressDeniedForCoin(
                    FfiConverterTypeAddress.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 37:
                return new ExecutionError.CoinTypeGlobalPause(
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 38:
                return new ExecutionError.ExecutionCancelledDueToRandomnessUnavailable(
                );
            case 39:
                return new ExecutionError.InvalidLinkage(
                );
            default:
                throw new InternalException(string.Format("invalid enum value '{0}' in FfiConverterTypeExecutionError.Read()", value));
        }
    }

    public override int AllocationSize(ExecutionError value) {
        switch (value) {
            case ExecutionError.InsufficientGas variant_value:
                return 4;
            case ExecutionError.InvalidGasObject variant_value:
                return 4;
            case ExecutionError.InvariantViolation variant_value:
                return 4;
            case ExecutionError.FeatureNotYetSupported variant_value:
                return 4;
            case ExecutionError.ObjectTooBig variant_value:
                return 4
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@objectSize)
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@maxObjectSize);
            case ExecutionError.PackageTooBig variant_value:
                return 4
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@objectSize)
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@maxObjectSize);
            case ExecutionError.CircularObjectOwnership variant_value:
                return 4
                    + FfiConverterTypeObjectId.INSTANCE.AllocationSize(variant_value.@object);
            case ExecutionError.InsufficientCoinBalance variant_value:
                return 4;
            case ExecutionError.CoinBalanceOverflow variant_value:
                return 4;
            case ExecutionError.PublishErrorNonZeroAddress variant_value:
                return 4;
            case ExecutionError.IotaMoveVerification variant_value:
                return 4;
            case ExecutionError.MovePrimitiveRuntime variant_value:
                return 4
                    + FfiConverterOptionalTypeMoveLocation.INSTANCE.AllocationSize(variant_value.@location);
            case ExecutionError.MoveAbort variant_value:
                return 4
                    + FfiConverterTypeMoveLocation.INSTANCE.AllocationSize(variant_value.@location)
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@code);
            case ExecutionError.VmVerificationOrDeserialization variant_value:
                return 4;
            case ExecutionError.VmInvariantViolation variant_value:
                return 4;
            case ExecutionError.FunctionNotFound variant_value:
                return 4;
            case ExecutionError.ArityMismatch variant_value:
                return 4;
            case ExecutionError.TypeArityMismatch variant_value:
                return 4;
            case ExecutionError.NonEntryFunctionInvoked variant_value:
                return 4;
            case ExecutionError.CommandArgument variant_value:
                return 4
                    + FfiConverterUInt16.INSTANCE.AllocationSize(variant_value.@argument)
                    + FfiConverterTypeCommandArgumentError.INSTANCE.AllocationSize(variant_value.@kind);
            case ExecutionError.TypeArgument variant_value:
                return 4
                    + FfiConverterUInt16.INSTANCE.AllocationSize(variant_value.@typeArgument)
                    + FfiConverterTypeTypeArgumentError.INSTANCE.AllocationSize(variant_value.@kind);
            case ExecutionError.UnusedValueWithoutDrop variant_value:
                return 4
                    + FfiConverterUInt16.INSTANCE.AllocationSize(variant_value.@result)
                    + FfiConverterUInt16.INSTANCE.AllocationSize(variant_value.@subresult);
            case ExecutionError.InvalidPublicFunctionReturnType variant_value:
                return 4
                    + FfiConverterUInt16.INSTANCE.AllocationSize(variant_value.@index);
            case ExecutionError.InvalidTransferObject variant_value:
                return 4;
            case ExecutionError.EffectsTooLarge variant_value:
                return 4
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@currentSize)
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@maxSize);
            case ExecutionError.PublishUpgradeMissingDependency variant_value:
                return 4;
            case ExecutionError.PublishUpgradeDependencyDowngrade variant_value:
                return 4;
            case ExecutionError.PackageUpgrade variant_value:
                return 4
                    + FfiConverterTypePackageUpgradeError.INSTANCE.AllocationSize(variant_value.@kind);
            case ExecutionError.WrittenObjectsTooLarge variant_value:
                return 4
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@objectSize)
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@maxObjectSize);
            case ExecutionError.CertificateDenied variant_value:
                return 4;
            case ExecutionError.IotaMoveVerificationTimeout variant_value:
                return 4;
            case ExecutionError.SharedObjectOperationNotAllowed variant_value:
                return 4;
            case ExecutionError.InputObjectDeleted variant_value:
                return 4;
            case ExecutionError.ExecutionCancelledDueToSharedObjectCongestion variant_value:
                return 4
                    + FfiConverterSequenceTypeObjectId.INSTANCE.AllocationSize(variant_value.@congestedObjects);
            case ExecutionError.ExecutionCancelledDueToSharedObjectCongestionV2 variant_value:
                return 4
                    + FfiConverterSequenceTypeObjectId.INSTANCE.AllocationSize(variant_value.@congestedObjects)
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@suggestedGasPrice);
            case ExecutionError.AddressDeniedForCoin variant_value:
                return 4
                    + FfiConverterTypeAddress.INSTANCE.AllocationSize(variant_value.@address)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@coinType);
            case ExecutionError.CoinTypeGlobalPause variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@coinType);
            case ExecutionError.ExecutionCancelledDueToRandomnessUnavailable variant_value:
                return 4;
            case ExecutionError.InvalidLinkage variant_value:
                return 4;
            default:
                throw new InternalException(string.Format("invalid enum value '{0}' in FfiConverterTypeExecutionError.AllocationSize()", value));
        }
    }

    public override void Write(ExecutionError value, BigEndianStream stream) {
        switch (value) {
            case ExecutionError.InsufficientGas variant_value:
                stream.WriteInt(1);
                break;
            case ExecutionError.InvalidGasObject variant_value:
                stream.WriteInt(2);
                break;
            case ExecutionError.InvariantViolation variant_value:
                stream.WriteInt(3);
                break;
            case ExecutionError.FeatureNotYetSupported variant_value:
                stream.WriteInt(4);
                break;
            case ExecutionError.ObjectTooBig variant_value:
                stream.WriteInt(5);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@objectSize, stream);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@maxObjectSize, stream);
                break;
            case ExecutionError.PackageTooBig variant_value:
                stream.WriteInt(6);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@objectSize, stream);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@maxObjectSize, stream);
                break;
            case ExecutionError.CircularObjectOwnership variant_value:
                stream.WriteInt(7);
                FfiConverterTypeObjectId.INSTANCE.Write(variant_value.@object, stream);
                break;
            case ExecutionError.InsufficientCoinBalance variant_value:
                stream.WriteInt(8);
                break;
            case ExecutionError.CoinBalanceOverflow variant_value:
                stream.WriteInt(9);
                break;
            case ExecutionError.PublishErrorNonZeroAddress variant_value:
                stream.WriteInt(10);
                break;
            case ExecutionError.IotaMoveVerification variant_value:
                stream.WriteInt(11);
                break;
            case ExecutionError.MovePrimitiveRuntime variant_value:
                stream.WriteInt(12);
                FfiConverterOptionalTypeMoveLocation.INSTANCE.Write(variant_value.@location, stream);
                break;
            case ExecutionError.MoveAbort variant_value:
                stream.WriteInt(13);
                FfiConverterTypeMoveLocation.INSTANCE.Write(variant_value.@location, stream);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@code, stream);
                break;
            case ExecutionError.VmVerificationOrDeserialization variant_value:
                stream.WriteInt(14);
                break;
            case ExecutionError.VmInvariantViolation variant_value:
                stream.WriteInt(15);
                break;
            case ExecutionError.FunctionNotFound variant_value:
                stream.WriteInt(16);
                break;
            case ExecutionError.ArityMismatch variant_value:
                stream.WriteInt(17);
                break;
            case ExecutionError.TypeArityMismatch variant_value:
                stream.WriteInt(18);
                break;
            case ExecutionError.NonEntryFunctionInvoked variant_value:
                stream.WriteInt(19);
                break;
            case ExecutionError.CommandArgument variant_value:
                stream.WriteInt(20);
                FfiConverterUInt16.INSTANCE.Write(variant_value.@argument, stream);
                FfiConverterTypeCommandArgumentError.INSTANCE.Write(variant_value.@kind, stream);
                break;
            case ExecutionError.TypeArgument variant_value:
                stream.WriteInt(21);
                FfiConverterUInt16.INSTANCE.Write(variant_value.@typeArgument, stream);
                FfiConverterTypeTypeArgumentError.INSTANCE.Write(variant_value.@kind, stream);
                break;
            case ExecutionError.UnusedValueWithoutDrop variant_value:
                stream.WriteInt(22);
                FfiConverterUInt16.INSTANCE.Write(variant_value.@result, stream);
                FfiConverterUInt16.INSTANCE.Write(variant_value.@subresult, stream);
                break;
            case ExecutionError.InvalidPublicFunctionReturnType variant_value:
                stream.WriteInt(23);
                FfiConverterUInt16.INSTANCE.Write(variant_value.@index, stream);
                break;
            case ExecutionError.InvalidTransferObject variant_value:
                stream.WriteInt(24);
                break;
            case ExecutionError.EffectsTooLarge variant_value:
                stream.WriteInt(25);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@currentSize, stream);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@maxSize, stream);
                break;
            case ExecutionError.PublishUpgradeMissingDependency variant_value:
                stream.WriteInt(26);
                break;
            case ExecutionError.PublishUpgradeDependencyDowngrade variant_value:
                stream.WriteInt(27);
                break;
            case ExecutionError.PackageUpgrade variant_value:
                stream.WriteInt(28);
                FfiConverterTypePackageUpgradeError.INSTANCE.Write(variant_value.@kind, stream);
                break;
            case ExecutionError.WrittenObjectsTooLarge variant_value:
                stream.WriteInt(29);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@objectSize, stream);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@maxObjectSize, stream);
                break;
            case ExecutionError.CertificateDenied variant_value:
                stream.WriteInt(30);
                break;
            case ExecutionError.IotaMoveVerificationTimeout variant_value:
                stream.WriteInt(31);
                break;
            case ExecutionError.SharedObjectOperationNotAllowed variant_value:
                stream.WriteInt(32);
                break;
            case ExecutionError.InputObjectDeleted variant_value:
                stream.WriteInt(33);
                break;
            case ExecutionError.ExecutionCancelledDueToSharedObjectCongestion variant_value:
                stream.WriteInt(34);
                FfiConverterSequenceTypeObjectId.INSTANCE.Write(variant_value.@congestedObjects, stream);
                break;
            case ExecutionError.ExecutionCancelledDueToSharedObjectCongestionV2 variant_value:
                stream.WriteInt(35);
                FfiConverterSequenceTypeObjectId.INSTANCE.Write(variant_value.@congestedObjects, stream);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@suggestedGasPrice, stream);
                break;
            case ExecutionError.AddressDeniedForCoin variant_value:
                stream.WriteInt(36);
                FfiConverterTypeAddress.INSTANCE.Write(variant_value.@address, stream);
                FfiConverterString.INSTANCE.Write(variant_value.@coinType, stream);
                break;
            case ExecutionError.CoinTypeGlobalPause variant_value:
                stream.WriteInt(37);
                FfiConverterString.INSTANCE.Write(variant_value.@coinType, stream);
                break;
            case ExecutionError.ExecutionCancelledDueToRandomnessUnavailable variant_value:
                stream.WriteInt(38);
                break;
            case ExecutionError.InvalidLinkage variant_value:
                stream.WriteInt(39);
                break;
            default:
                throw new InternalException(string.Format("invalid enum value '{0}' in FfiConverterTypeExecutionError.Write()", value));
        }
    }
}







/// <summary>
/// The status of an executed Transaction
///
/// # BCS
///
/// The BCS serialized form for this type is defined by the following ABNF:
///
/// ```text
/// execution-status = success / failure
/// success = %d00
/// failure = %d01 execution-error (option u64)
/// ```
/// </summary>
public record ExecutionStatus: IDisposable  {
    
    /// <summary>
    /// The Transaction successfully executed.
    /// </summary>
    public record Success: ExecutionStatus {}
    
    
    /// <summary>
    /// The Transaction didn't execute successfully.
    ///
    /// Failed transactions are still committed to the blockchain but any
    /// intended effects are rolled back to prior to this transaction
    /// executing with the caveat that gas objects are still smashed and gas
    /// usage is still charged.
    /// </summary>
    public record Failure (
        ExecutionError @error,
        ulong? @command
    ) : ExecutionStatus {}
    

    
    public void Dispose() {
        switch (this) {
            case ExecutionStatus.Success variant_value:
                break;
            case ExecutionStatus.Failure variant_value:
                
    FFIObjectUtil.DisposeAll(
            variant_value.@error,
            variant_value.@command);
                break;
            default:
                throw new InternalException(string.Format("invalid enum value '{0}' in ExecutionStatus.Dispose()", this));
        }
    }
    
}

class FfiConverterTypeExecutionStatus : FfiConverterRustBuffer<ExecutionStatus>{
    public static FfiConverterRustBuffer<ExecutionStatus> INSTANCE = new FfiConverterTypeExecutionStatus();

    public override ExecutionStatus Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new ExecutionStatus.Success(
                );
            case 2:
                return new ExecutionStatus.Failure(
                    FfiConverterTypeExecutionError.INSTANCE.Read(stream),
                    FfiConverterOptionalUInt64.INSTANCE.Read(stream)
                );
            default:
                throw new InternalException(string.Format("invalid enum value '{0}' in FfiConverterTypeExecutionStatus.Read()", value));
        }
    }

    public override int AllocationSize(ExecutionStatus value) {
        switch (value) {
            case ExecutionStatus.Success variant_value:
                return 4;
            case ExecutionStatus.Failure variant_value:
                return 4
                    + FfiConverterTypeExecutionError.INSTANCE.AllocationSize(variant_value.@error)
                    + FfiConverterOptionalUInt64.INSTANCE.AllocationSize(variant_value.@command);
            default:
                throw new InternalException(string.Format("invalid enum value '{0}' in FfiConverterTypeExecutionStatus.AllocationSize()", value));
        }
    }

    public override void Write(ExecutionStatus value, BigEndianStream stream) {
        switch (value) {
            case ExecutionStatus.Success variant_value:
                stream.WriteInt(1);
                break;
            case ExecutionStatus.Failure variant_value:
                stream.WriteInt(2);
                FfiConverterTypeExecutionError.INSTANCE.Write(variant_value.@error, stream);
                FfiConverterOptionalUInt64.INSTANCE.Write(variant_value.@command, stream);
                break;
            default:
                throw new InternalException(string.Format("invalid enum value '{0}' in FfiConverterTypeExecutionStatus.Write()", value));
        }
    }
}







