/// <summary>
/// Intent errors.
/// </summary>
public class IntentException: UniffiException {
    IntentException(string message): base(message) {}

    // Each variant is a nested class
    // Flat enums carries a string error message, so no special implementation is necessary.
    
    /// <summary>
    /// Invalid bytes for Intent
    /// </summary>
    public class Bytes: IntentException {
        public Bytes(string message): base(message) {}
    }
    
    /// <summary>
    /// Invalid hex string for Intent
    /// </summary>
    public class Hex: IntentException {
        public Hex(string message): base(message) {}
    }
    
    /// <summary>
    /// Invalid Scope for Intent
    /// </summary>
    public class Scope: IntentException {
        public Scope(string message): base(message) {}
    }
    
    /// <summary>
    /// Invalid Version for Intent
    /// </summary>
    public class Version: IntentException {
        public Version(string message): base(message) {}
    }
    
    /// <summary>
    /// Invalid AppId for Intent
    /// </summary>
    public class AppId: IntentException {
        public AppId(string message): base(message) {}
    }
    
}

class FfiConverterTypeIntentError : FfiConverterRustBuffer<IntentException>, CallStatusErrorHandler<IntentException> {
    public static FfiConverterTypeIntentError INSTANCE = new FfiConverterTypeIntentError();

    public override IntentException Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1: return new IntentException.Bytes(FfiConverterString.INSTANCE.Read(stream));
            case 2: return new IntentException.Hex(FfiConverterString.INSTANCE.Read(stream));
            case 3: return new IntentException.Scope(FfiConverterString.INSTANCE.Read(stream));
            case 4: return new IntentException.Version(FfiConverterString.INSTANCE.Read(stream));
            case 5: return new IntentException.AppId(FfiConverterString.INSTANCE.Read(stream));
            default:
                throw new InternalException(string.Format("invalid error value '{0}' in FfiConverterTypeIntentError.Read()", value));
        }
    }

    public override int AllocationSize(IntentException value) {
        return 4 + FfiConverterString.INSTANCE.AllocationSize(value.Message);
    }

    public override void Write(IntentException value, BigEndianStream stream) {
        switch (value) {
            case IntentException.Bytes:
                stream.WriteInt(1);
                break;
            case IntentException.Hex:
                stream.WriteInt(2);
                break;
            case IntentException.Scope:
                stream.WriteInt(3);
                break;
            case IntentException.Version:
                stream.WriteInt(4);
                break;
            case IntentException.AppId:
                stream.WriteInt(5);
                break;
            default:
                throw new InternalException(string.Format("invalid error value '{0}' in FfiConverterTypeIntentError.Write()", value));
        }
    }
}





/// <summary>
/// Byte signifying the scope of an Intent
///
/// This enum specifies the intent scope. Two intents for different scopes
/// should never collide, so no signature provided for one intent scope can be
/// used for another, even when the serialized data itself may be the same.
///
/// # BCS
///
/// The BCS serialized form for this type is defined by the following ABNF:
///
/// ```text
/// intent-scope = u8
/// ```
/// </summary>
public enum IntentScope: int {
    
    /// <summary>
    /// Used for a user signature on a transaction data.
    /// </summary>
    TransactionData,
    /// <summary>
    /// Used for an authority signature on transaction effects.
    /// </summary>
    TransactionEffects,
    /// <summary>
    /// Used for an authority signature on a checkpoint summary.
    /// </summary>
    CheckpointSummary,
    /// <summary>
    /// Used for a user signature on a personal message.
    /// </summary>
    PersonalMessage,
    /// <summary>
    /// Used for an authority signature on a user signed transaction.
    /// </summary>
    SenderSignedTransaction,
    /// <summary>
    /// Used as a signature representing an authority's proof of possession of
    /// its authority key.
    /// </summary>
    ProofOfPossession,
    /// <summary>
    /// Deprecated. Should not be reused. Introduced for bridge purposes but was
    /// never included in messages.
    /// </summary>
    BridgeEventDeprecated,
    /// <summary>
    /// Used for consensus authority signature on block's digest.
    /// </summary>
    ConsensusBlock,
    /// <summary>
    /// Used for reporting peer addresses in discovery
    /// </summary>
    DiscoveryPeers,
    /// <summary>
    /// Used for authority capabilities from non-committee authorities.
    /// </summary>
    AuthorityCapabilities
}

