    }
}







/// <summary>
/// State of an object prior to execution
///
/// If an object exists (at root-level) in the store prior to this transaction,
/// it should be Data, otherwise it's Missing, e.g. wrapped objects should be
/// Missing.
///
/// # BCS
///
/// The BCS serialized form for this type is defined by the following ABNF:
///
/// ```text
/// object-in = object-in-missing / object-in-data
///
/// object-in-missing = %d00
/// object-in-data    = %d01 u64 digest owner
/// ```
/// </summary>
public record ObjectIn: IDisposable  {
    
    public record Missing: ObjectIn {}
    
    
    /// <summary>
    /// The old version, digest and owner.
    /// </summary>
    public record Data (
        ulong @version,
        Digest @digest,
        Owner @owner
    ) : ObjectIn {}
    

    
    public void Dispose() {
        switch (this) {
            case ObjectIn.Missing variant_value:
                break;
            case ObjectIn.Data variant_value:
                
    FFIObjectUtil.DisposeAll(
            variant_value.@version,
            variant_value.@digest,
            variant_value.@owner);
                break;
            default:
                throw new InternalException(string.Format("invalid enum value '{0}' in ObjectIn.Dispose()", this));
        }
    }
    
}

class FfiConverterTypeObjectIn : FfiConverterRustBuffer<ObjectIn>{
    public static FfiConverterRustBuffer<ObjectIn> INSTANCE = new FfiConverterTypeObjectIn();

    public override ObjectIn Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new ObjectIn.Missing(
                );
            case 2:
                return new ObjectIn.Data(
                    FfiConverterUInt64.INSTANCE.Read(stream),
                    FfiConverterTypeDigest.INSTANCE.Read(stream),
                    FfiConverterTypeOwner.INSTANCE.Read(stream)
                );
            default:
                throw new InternalException(string.Format("invalid enum value '{0}' in FfiConverterTypeObjectIn.Read()", value));
        }
    }

    public override int AllocationSize(ObjectIn value) {
        switch (value) {
            case ObjectIn.Missing variant_value:
                return 4;
            case ObjectIn.Data variant_value:
                return 4
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@version)
                    + FfiConverterTypeDigest.INSTANCE.AllocationSize(variant_value.@digest)
                    + FfiConverterTypeOwner.INSTANCE.AllocationSize(variant_value.@owner);
            default:
                throw new InternalException(string.Format("invalid enum value '{0}' in FfiConverterTypeObjectIn.AllocationSize()", value));
        }
    }

    public override void Write(ObjectIn value, BigEndianStream stream) {
        switch (value) {
            case ObjectIn.Missing variant_value:
                stream.WriteInt(1);
                break;
            case ObjectIn.Data variant_value:
                stream.WriteInt(2);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@version, stream);
                FfiConverterTypeDigest.INSTANCE.Write(variant_value.@digest, stream);
                FfiConverterTypeOwner.INSTANCE.Write(variant_value.@owner, stream);
                break;
            default:
                throw new InternalException(string.Format("invalid enum value '{0}' in FfiConverterTypeObjectIn.Write()", value));
        }
    }
}







/// <summary>
/// State of an object after execution
///
/// # BCS
///
/// The BCS serialized form for this type is defined by the following ABNF:
///
/// ```text
/// object-out  =  object-out-missing
/// =/ object-out-object-write
/// =/ object-out-package-write
///
///
/// object-out-missing        = %d00
/// object-out-object-write   = %d01 digest owner
/// object-out-package-write  = %d02 version digest
/// ```
/// </summary>
public record ObjectOut: IDisposable  {
    
    /// <summary>
    /// Same definition as in ObjectIn.
    /// </summary>
    public record Missing: ObjectOut {}
    
    
    /// <summary>
    /// Any written object, including all of mutated, created, unwrapped today.
    /// </summary>
    public record ObjectWrite (
        Digest @digest,
        Owner @owner
    ) : ObjectOut {}
    
    /// <summary>
    /// Packages writes need to be tracked separately with version because
    /// we don't use lamport version for package publish and upgrades.
    /// </summary>
    public record PackageWrite (
        ulong @version,
        Digest @digest
    ) : ObjectOut {}
    

    
    public void Dispose() {
        switch (this) {
            case ObjectOut.Missing variant_value:
                break;
            case ObjectOut.ObjectWrite variant_value:
                
    FFIObjectUtil.DisposeAll(
            variant_value.@digest,
            variant_value.@owner);
                break;
            case ObjectOut.PackageWrite variant_value:
                
    FFIObjectUtil.DisposeAll(
            variant_value.@version,
            variant_value.@digest);
                break;
            default:
                throw new InternalException(string.Format("invalid enum value '{0}' in ObjectOut.Dispose()", this));
        }
    }
    
}

class FfiConverterTypeObjectOut : FfiConverterRustBuffer<ObjectOut>{
    public static FfiConverterRustBuffer<ObjectOut> INSTANCE = new FfiConverterTypeObjectOut();

    public override ObjectOut Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new ObjectOut.Missing(
                );
            case 2:
                return new ObjectOut.ObjectWrite(
                    FfiConverterTypeDigest.INSTANCE.Read(stream),
                    FfiConverterTypeOwner.INSTANCE.Read(stream)
                );
            case 3:
                return new ObjectOut.PackageWrite(
                    FfiConverterUInt64.INSTANCE.Read(stream),
                    FfiConverterTypeDigest.INSTANCE.Read(stream)
                );
            default:
                throw new InternalException(string.Format("invalid enum value '{0}' in FfiConverterTypeObjectOut.Read()", value));
        }
    }

    public override int AllocationSize(ObjectOut value) {
        switch (value) {
            case ObjectOut.Missing variant_value:
                return 4;
            case ObjectOut.ObjectWrite variant_value:
                return 4
                    + FfiConverterTypeDigest.INSTANCE.AllocationSize(variant_value.@digest)
                    + FfiConverterTypeOwner.INSTANCE.AllocationSize(variant_value.@owner);
            case ObjectOut.PackageWrite variant_value:
                return 4
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@version)
                    + FfiConverterTypeDigest.INSTANCE.AllocationSize(variant_value.@digest);
            default:
                throw new InternalException(string.Format("invalid enum value '{0}' in FfiConverterTypeObjectOut.AllocationSize()", value));
        }
    }

    public override void Write(ObjectOut value, BigEndianStream stream) {
        switch (value) {
            case ObjectOut.Missing variant_value:
                stream.WriteInt(1);
                break;
            case ObjectOut.ObjectWrite variant_value:
                stream.WriteInt(2);
                FfiConverterTypeDigest.INSTANCE.Write(variant_value.@digest, stream);
                FfiConverterTypeOwner.INSTANCE.Write(variant_value.@owner, stream);
                break;
            case ObjectOut.PackageWrite variant_value:
                stream.WriteInt(3);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@version, stream);
                FfiConverterTypeDigest.INSTANCE.Write(variant_value.@digest, stream);
                break;
            default:
                throw new InternalException(string.Format("invalid enum value '{0}' in FfiConverterTypeObjectOut.Write()", value));
        }
    }
}







/// <summary>
/// An error with a upgrading a package
///
/// # BCS
///
/// The BCS serialized form for this type is defined by the following ABNF:
///
/// ```text
/// package-upgrade-error = unable-to-fetch-package /
/// not-a-package           /
/// incompatible-upgrade    /
/// digest-does-not-match   /
/// unknown-upgrade-policy  /
/// package-id-does-not-match
///
/// unable-to-fetch-package     = %d00 object-id
/// not-a-package               = %d01 object-id
/// incompatible-upgrade        = %d02
/// digest-does-not-match       = %d03 digest
/// unknown-upgrade-policy      = %d04 u8
/// package-id-does-not-match   = %d05 object-id object-id
/// ```
/// </summary>
public record PackageUpgradeError: IDisposable  {
    
    /// <summary>
    /// Unable to fetch package
    /// </summary>
    public record UnableToFetchPackage (
        ObjectId @packageId
    ) : PackageUpgradeError {}
    
    /// <summary>
    /// Object is not a package
    /// </summary>
    public record NotAPackage (
        ObjectId @objectId
    ) : PackageUpgradeError {}
    
    /// <summary>
    /// Package upgrade is incompatible with previous version
    /// </summary>
    public record IncompatibleUpgrade: PackageUpgradeError {}
    
    
    /// <summary>
    /// Digest in upgrade ticket and computed digest differ
    /// </summary>
    public record DigestDoesNotMatch (
        Digest @digest
    ) : PackageUpgradeError {}
    
    /// <summary>
    /// Upgrade policy is not valid
    /// </summary>
    public record UnknownUpgradePolicy (
        byte @policy
    ) : PackageUpgradeError {}
    
    /// <summary>
    /// PackageId does not matach PackageId in upgrade ticket
    /// </summary>
    public record PackageIdDoesNotMatch (
        ObjectId @packageId,
        ObjectId @ticketId
    ) : PackageUpgradeError {}
    

    
    public void Dispose() {
        switch (this) {
            case PackageUpgradeError.UnableToFetchPackage variant_value:
                
    FFIObjectUtil.DisposeAll(
            variant_value.@packageId);
                break;
            case PackageUpgradeError.NotAPackage variant_value:
                
    FFIObjectUtil.DisposeAll(
            variant_value.@objectId);
                break;
            case PackageUpgradeError.IncompatibleUpgrade variant_value:
                break;
            case PackageUpgradeError.DigestDoesNotMatch variant_value:
                
    FFIObjectUtil.DisposeAll(
            variant_value.@digest);
                break;
            case PackageUpgradeError.UnknownUpgradePolicy variant_value:
                
    FFIObjectUtil.DisposeAll(
            variant_value.@policy);
                break;
            case PackageUpgradeError.PackageIdDoesNotMatch variant_value:
                
    FFIObjectUtil.DisposeAll(
            variant_value.@packageId,
            variant_value.@ticketId);
                break;
            default:
                throw new InternalException(string.Format("invalid enum value '{0}' in PackageUpgradeError.Dispose()", this));
        }
    }
    
}

class FfiConverterTypePackageUpgradeError : FfiConverterRustBuffer<PackageUpgradeError>{
    public static FfiConverterRustBuffer<PackageUpgradeError> INSTANCE = new FfiConverterTypePackageUpgradeError();

    public override PackageUpgradeError Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new PackageUpgradeError.UnableToFetchPackage(
                    FfiConverterTypeObjectId.INSTANCE.Read(stream)
                );
            case 2:
                return new PackageUpgradeError.NotAPackage(
                    FfiConverterTypeObjectId.INSTANCE.Read(stream)
                );
            case 3:
                return new PackageUpgradeError.IncompatibleUpgrade(
                );
            case 4:
                return new PackageUpgradeError.DigestDoesNotMatch(
                    FfiConverterTypeDigest.INSTANCE.Read(stream)
                );
            case 5:
                return new PackageUpgradeError.UnknownUpgradePolicy(
                    FfiConverterUInt8.INSTANCE.Read(stream)
                );
            case 6:
                return new PackageUpgradeError.PackageIdDoesNotMatch(
                    FfiConverterTypeObjectId.INSTANCE.Read(stream),
                    FfiConverterTypeObjectId.INSTANCE.Read(stream)
                );
            default:
                throw new InternalException(string.Format("invalid enum value '{0}' in FfiConverterTypePackageUpgradeError.Read()", value));
        }
    }

    public override int AllocationSize(PackageUpgradeError value) {
        switch (value) {
            case PackageUpgradeError.UnableToFetchPackage variant_value:
                return 4
                    + FfiConverterTypeObjectId.INSTANCE.AllocationSize(variant_value.@packageId);
            case PackageUpgradeError.NotAPackage variant_value:
                return 4
                    + FfiConverterTypeObjectId.INSTANCE.AllocationSize(variant_value.@objectId);
            case PackageUpgradeError.IncompatibleUpgrade variant_value:
                return 4;
            case PackageUpgradeError.DigestDoesNotMatch variant_value:
                return 4
                    + FfiConverterTypeDigest.INSTANCE.AllocationSize(variant_value.@digest);
            case PackageUpgradeError.UnknownUpgradePolicy variant_value:
                return 4
                    + FfiConverterUInt8.INSTANCE.AllocationSize(variant_value.@policy);
            case PackageUpgradeError.PackageIdDoesNotMatch variant_value:
                return 4
                    + FfiConverterTypeObjectId.INSTANCE.AllocationSize(variant_value.@packageId)
                    + FfiConverterTypeObjectId.INSTANCE.AllocationSize(variant_value.@ticketId);
            default:
                throw new InternalException(string.Format("invalid enum value '{0}' in FfiConverterTypePackageUpgradeError.AllocationSize()", value));
        }
    }

    public override void Write(PackageUpgradeError value, BigEndianStream stream) {
        switch (value) {
            case PackageUpgradeError.UnableToFetchPackage variant_value:
                stream.WriteInt(1);
                FfiConverterTypeObjectId.INSTANCE.Write(variant_value.@packageId, stream);
                break;
            case PackageUpgradeError.NotAPackage variant_value:
                stream.WriteInt(2);
                FfiConverterTypeObjectId.INSTANCE.Write(variant_value.@objectId, stream);
                break;
            case PackageUpgradeError.IncompatibleUpgrade variant_value:
                stream.WriteInt(3);
                break;
            case PackageUpgradeError.DigestDoesNotMatch variant_value:
                stream.WriteInt(4);
                FfiConverterTypeDigest.INSTANCE.Write(variant_value.@digest, stream);
                break;
            case PackageUpgradeError.UnknownUpgradePolicy variant_value:
                stream.WriteInt(5);
                FfiConverterUInt8.INSTANCE.Write(variant_value.@policy, stream);
                break;
            case PackageUpgradeError.PackageIdDoesNotMatch variant_value:
                stream.WriteInt(6);
                FfiConverterTypeObjectId.INSTANCE.Write(variant_value.@packageId, stream);
                FfiConverterTypeObjectId.INSTANCE.Write(variant_value.@ticketId, stream);
                break;
            default:
                throw new InternalException(string.Format("invalid enum value '{0}' in FfiConverterTypePackageUpgradeError.Write()", value));
        }
    }
}







public class SdkFfiException: UniffiException {
    SdkFfiException(string message): base(message) {}

    // Each variant is a nested class
    // Flat enums carries a string error message, so no special implementation is necessary.
    
    public class Generic: SdkFfiException {
        public Generic(string message): base(message) {}
    }
    
}

class FfiConverterTypeSdkFfiError : FfiConverterRustBuffer<SdkFfiException>, CallStatusErrorHandler<SdkFfiException> {
    public static FfiConverterTypeSdkFfiError INSTANCE = new FfiConverterTypeSdkFfiError();

    public override SdkFfiException Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1: return new SdkFfiException.Generic(FfiConverterString.INSTANCE.Read(stream));
            default:
                throw new InternalException(string.Format("invalid error value '{0}' in FfiConverterTypeSdkFfiError.Read()", value));
        }
    }

    public override int AllocationSize(SdkFfiException value) {
        return 4 + FfiConverterString.INSTANCE.AllocationSize(value.Message);
    }

    public override void Write(SdkFfiException value, BigEndianStream stream) {
        switch (value) {
            case SdkFfiException.Generic:
                stream.WriteInt(1);
                break;
            default:
                throw new InternalException(string.Format("invalid error value '{0}' in FfiConverterTypeSdkFfiError.Write()", value));
        }
    }
}





/// <summary>
/// Flag use to disambiguate the signature schemes supported by IOTA.
///
/// # BCS
///
/// The BCS serialized form for this type is defined by the following ABNF:
///
/// ```text
/// signature-scheme = ed25519-flag / secp256k1-flag / secp256r1-flag /
/// multisig-flag / bls-flag / zklogin-auth-flag-deprecated / passkey-auth-flag /
/// move-auth-flag
/// ed25519-flag                    = %d00
/// secp256k1-flag                  = %d01
/// secp256r1-flag                  = %d02
/// multisig-flag                   = %d03
/// bls-flag                        = %d04
/// zklogin-auth-flag-deprecated    = %d05
/// passkey-auth-flag               = %d06
/// move-auth-flag                  = %d07
/// ```
/// </summary>
public enum SignatureScheme: int {
    
    Ed25519,
    Secp256k1,
    Secp256r1,
    Multisig,
    Bls12381,
    ZkLoginAuthenticatorDeprecated,
    PasskeyAuthenticator,
    MoveAuthenticator
}

class FfiConverterTypeSignatureScheme: FfiConverterRustBuffer<SignatureScheme> {
    public static FfiConverterTypeSignatureScheme INSTANCE = new FfiConverterTypeSignatureScheme();

    public override SignatureScheme Read(BigEndianStream stream) {
        var value = stream.ReadInt() - 1;
        if (Enum.IsDefined(typeof(SignatureScheme), value)) {
            return (SignatureScheme)value;
        } else {
            throw new InternalException(string.Format("invalid enum value '{0}' in FfiConverterTypeSignatureScheme.Read()", value));
        }
    }

    public override int AllocationSize(SignatureScheme value) {
        return 4;
    }

    public override void Write(SignatureScheme value, BigEndianStream stream) {
        stream.WriteInt((int)value + 1);
    }
}







/// <summary>
/// A transaction argument used in programmable transactions.
/// </summary>
public record TransactionArgument {
    
    /// <summary>
    /// Reference to the gas coin.
    /// </summary>
    public record GasCoin: TransactionArgument {}
    
    
    /// <summary>
    /// An input to the programmable transaction block.
    /// </summary>
    public record Input (
        uint @index
    ) : TransactionArgument {}
    
    /// <summary>
    /// The result of another transaction command.
    /// </summary>
    public record Result (
        uint @cmd,
        uint? @index
    ) : TransactionArgument {}
    

    
}

class FfiConverterTypeTransactionArgument : FfiConverterRustBuffer<TransactionArgument>{
    public static FfiConverterRustBuffer<TransactionArgument> INSTANCE = new FfiConverterTypeTransactionArgument();

    public override TransactionArgument Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new TransactionArgument.GasCoin(
                );
            case 2:
                return new TransactionArgument.Input(
                    FfiConverterUInt32.INSTANCE.Read(stream)
                );
            case 3:
                return new TransactionArgument.Result(
                    FfiConverterUInt32.INSTANCE.Read(stream),
                    FfiConverterOptionalUInt32.INSTANCE.Read(stream)
                );
            default:
                throw new InternalException(string.Format("invalid enum value '{0}' in FfiConverterTypeTransactionArgument.Read()", value));
        }
    }

    public override int AllocationSize(TransactionArgument value) {
        switch (value) {
            case TransactionArgument.GasCoin variant_value:
                return 4;
            case TransactionArgument.Input variant_value:
                return 4
                    + FfiConverterUInt32.INSTANCE.AllocationSize(variant_value.@index);
            case TransactionArgument.Result variant_value:
                return 4
                    + FfiConverterUInt32.INSTANCE.AllocationSize(variant_value.@cmd)
                    + FfiConverterOptionalUInt32.INSTANCE.AllocationSize(variant_value.@index);
            default:
                throw new InternalException(string.Format("invalid enum value '{0}' in FfiConverterTypeTransactionArgument.AllocationSize()", value));
        }
    }

    public override void Write(TransactionArgument value, BigEndianStream stream) {
        switch (value) {
            case TransactionArgument.GasCoin variant_value:
                stream.WriteInt(1);
                break;
            case TransactionArgument.Input variant_value:
                stream.WriteInt(2);
                FfiConverterUInt32.INSTANCE.Write(variant_value.@index, stream);
                break;
            case TransactionArgument.Result variant_value:
                stream.WriteInt(3);
                FfiConverterUInt32.INSTANCE.Write(variant_value.@cmd, stream);
                FfiConverterOptionalUInt32.INSTANCE.Write(variant_value.@index, stream);
                break;
            default:
                throw new InternalException(string.Format("invalid enum value '{0}' in FfiConverterTypeTransactionArgument.Write()", value));
        }
    }
}







