/// <summary>
/// A TTL for a transaction
///
/// # BCS
///
/// The BCS serialized form for this type is defined by the following ABNF:
///
/// ```text
/// transaction-expiration =  %d00      ; none
/// =/ %d01 u64  ; epoch
/// ```
/// </summary>
public record TransactionExpiration {
    
    /// <summary>
    /// The transaction has no expiration
    /// </summary>
    public record None: TransactionExpiration {}
    
    
    /// <summary>
    /// Validators won't sign a transaction unless the expiration Epoch
    /// is greater than or equal to the current epoch
    /// </summary>
    public record Epoch (
        ulong @v1
    ) : TransactionExpiration {}
    

    
}

class FfiConverterTypeTransactionExpiration : FfiConverterRustBuffer<TransactionExpiration>{
    public static FfiConverterRustBuffer<TransactionExpiration> INSTANCE = new FfiConverterTypeTransactionExpiration();

    public override TransactionExpiration Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new TransactionExpiration.None(
                );
            case 2:
                return new TransactionExpiration.Epoch(
                    FfiConverterUInt64.INSTANCE.Read(stream)
                );
            default:
                throw new InternalException(string.Format("invalid enum value '{0}' in FfiConverterTypeTransactionExpiration.Read()", value));
        }
    }

    public override int AllocationSize(TransactionExpiration value) {
        switch (value) {
            case TransactionExpiration.None variant_value:
                return 4;
            case TransactionExpiration.Epoch variant_value:
                return 4
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@v1);
            default:
                throw new InternalException(string.Format("invalid enum value '{0}' in FfiConverterTypeTransactionExpiration.AllocationSize()", value));
        }
    }

    public override void Write(TransactionExpiration value, BigEndianStream stream) {
        switch (value) {
            case TransactionExpiration.None variant_value:
                stream.WriteInt(1);
                break;
            case TransactionExpiration.Epoch variant_value:
                stream.WriteInt(2);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@v1, stream);
                break;
            default:
                throw new InternalException(string.Format("invalid enum value '{0}' in FfiConverterTypeTransactionExpiration.Write()", value));
        }
    }
}







