/// <summary>
/// Type of unchanged shared object
///
/// # BCS
///
/// The BCS serialized form for this type is defined by the following ABNF:
///
/// ```text
/// unchanged-shared-object-kind =  read-only-root
/// =/ mutate-deleted
/// =/ read-deleted
/// =/ cancelled
/// =/ per-epoch-config
///
/// read-only-root      = %d00 u64 digest
/// mutate-deleted      = %d01 u64
/// read-deleted        = %d02 u64
/// cancelled           = %d03 u64
/// per-epoch-config    = %d04
/// ```
/// </summary>
public record UnchangedSharedKind: IDisposable  {
    
    /// <summary>
    /// Read-only shared objects from the input. We don't really need
    /// ObjectDigest for protocol correctness, but it will make it easier to
    /// verify untrusted read.
    /// </summary>
    public record ReadOnlyRoot (
        ulong @version,
        Digest @digest
    ) : UnchangedSharedKind {}
    
    /// <summary>
    /// Deleted shared objects that appear mutably/owned in the input.
    /// </summary>
    public record MutateDeleted (
        ulong @version
    ) : UnchangedSharedKind {}
    
    /// <summary>
    /// Deleted shared objects that appear as read-only in the input.
    /// </summary>
    public record ReadDeleted (
        ulong @version
    ) : UnchangedSharedKind {}
    
    /// <summary>
    /// Shared objects in cancelled transaction. The sequence number embed
    /// cancellation reason.
    /// </summary>
    public record Cancelled (
        ulong @version
    ) : UnchangedSharedKind {}
    
    /// <summary>
    /// Read of a per-epoch config object that should remain the same during an
    /// epoch.
    /// </summary>
    public record PerEpochConfig: UnchangedSharedKind {}
    
    

    
    public void Dispose() {
        switch (this) {
            case UnchangedSharedKind.ReadOnlyRoot variant_value:
                
    FFIObjectUtil.DisposeAll(
            variant_value.@version,
            variant_value.@digest);
                break;
            case UnchangedSharedKind.MutateDeleted variant_value:
                
    FFIObjectUtil.DisposeAll(
            variant_value.@version);
                break;
            case UnchangedSharedKind.ReadDeleted variant_value:
                
    FFIObjectUtil.DisposeAll(
            variant_value.@version);
                break;
            case UnchangedSharedKind.Cancelled variant_value:
                
    FFIObjectUtil.DisposeAll(
            variant_value.@version);
                break;
            case UnchangedSharedKind.PerEpochConfig variant_value:
                break;
            default:
                throw new InternalException(string.Format("invalid enum value '{0}' in UnchangedSharedKind.Dispose()", this));
        }
    }
    
}

class FfiConverterTypeUnchangedSharedKind : FfiConverterRustBuffer<UnchangedSharedKind>{
    public static FfiConverterRustBuffer<UnchangedSharedKind> INSTANCE = new FfiConverterTypeUnchangedSharedKind();

    public override UnchangedSharedKind Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new UnchangedSharedKind.ReadOnlyRoot(
                    FfiConverterUInt64.INSTANCE.Read(stream),
                    FfiConverterTypeDigest.INSTANCE.Read(stream)
                );
            case 2:
                return new UnchangedSharedKind.MutateDeleted(
                    FfiConverterUInt64.INSTANCE.Read(stream)
                );
            case 3:
                return new UnchangedSharedKind.ReadDeleted(
                    FfiConverterUInt64.INSTANCE.Read(stream)
                );
            case 4:
                return new UnchangedSharedKind.Cancelled(
                    FfiConverterUInt64.INSTANCE.Read(stream)
                );
            case 5:
                return new UnchangedSharedKind.PerEpochConfig(
                );
            default:
                throw new InternalException(string.Format("invalid enum value '{0}' in FfiConverterTypeUnchangedSharedKind.Read()", value));
        }
    }

    public override int AllocationSize(UnchangedSharedKind value) {
        switch (value) {
            case UnchangedSharedKind.ReadOnlyRoot variant_value:
                return 4
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@version)
                    + FfiConverterTypeDigest.INSTANCE.AllocationSize(variant_value.@digest);
            case UnchangedSharedKind.MutateDeleted variant_value:
                return 4
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@version);
            case UnchangedSharedKind.ReadDeleted variant_value:
                return 4
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@version);
            case UnchangedSharedKind.Cancelled variant_value:
                return 4
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@version);
            case UnchangedSharedKind.PerEpochConfig variant_value:
                return 4;
            default:
                throw new InternalException(string.Format("invalid enum value '{0}' in FfiConverterTypeUnchangedSharedKind.AllocationSize()", value));
        }
    }

    public override void Write(UnchangedSharedKind value, BigEndianStream stream) {
        switch (value) {
            case UnchangedSharedKind.ReadOnlyRoot variant_value:
                stream.WriteInt(1);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@version, stream);
                FfiConverterTypeDigest.INSTANCE.Write(variant_value.@digest, stream);
                break;
            case UnchangedSharedKind.MutateDeleted variant_value:
                stream.WriteInt(2);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@version, stream);
                break;
            case UnchangedSharedKind.ReadDeleted variant_value:
                stream.WriteInt(3);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@version, stream);
                break;
            case UnchangedSharedKind.Cancelled variant_value:
                stream.WriteInt(4);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@version, stream);
                break;
            case UnchangedSharedKind.PerEpochConfig variant_value:
                stream.WriteInt(5);
                break;
            default:
                throw new InternalException(string.Format("invalid enum value '{0}' in FfiConverterTypeUnchangedSharedKind.Write()", value));
        }
